# ============================================================
# 配置读写与并发保护
# ============================================================
_CONFIG_LOCK = threading.RLock()
_STORAGE_LOCK = threading.RLock()
_EXEC_LOCK = threading.RLock()


def _synchronized(lock):
    """串行化同一资源的读改写；原子写负责崩溃安全，锁负责避免丢更新。"""
    def deco(fn):
        def wrapped(*args, **kwargs):
            with lock:
                return fn(*args, **kwargs)
        wrapped.__name__ = fn.__name__
        wrapped.__doc__ = fn.__doc__
        return wrapped
    return deco


def load_config():
    cfg = dict(DEFAULT_CONFIG)
    if os.path.exists(CONFIG_PATH):
        try:
            with open(CONFIG_PATH, 'r', encoding='utf-8') as f:
                saved = json.load(f)
            if isinstance(saved, dict):
                cfg.update(saved)
            # 档位归一化(双保险): 配置文件中的非法/小写档位统一纠正, 防 UI 显示错位
            _t = str(cfg.get('security_tier') or 'T1').upper().strip()
            cfg['security_tier'] = _t if _t in SECURITY_TIERS else 'T1'
            # 旧「启用安全策略」总开关已被 SecurityGate 档位体系取代: 恒启用, 不再可关
            cfg['security_enabled'] = True
        except Exception:
            # 配置文件损坏时备份并重建
            try:
                os.replace(CONFIG_PATH, CONFIG_PATH + '.broken')
            except OSError:
                pass
    # 日志文件集中数据根目录; 配置未指定日志路径时指向默认位置并落盘
    cur_log = cfg.get('log_file') or ''
    if not cur_log:
        cfg['log_file'] = DEFAULT_LOG_FILE
        try:
            save_config(cfg)
        except OSError:
            pass
    if not cfg.get('token'):
        cfg['token'] = secrets.token_urlsafe(24)   # 首次启动自动生成令牌
        save_config(cfg)
    elif not os.path.exists(CONFIG_PATH):
        save_config(cfg)
    # 预解析允许目录
    cfg['_roots'] = [os.path.normcase(os.path.realpath(p)) for p in cfg.get('allowed_dirs') or []]
    for p in cfg.get('allowed_dirs') or []:
        try:
            os.makedirs(p, exist_ok=True)
        except OSError:
            pass
    return cfg


@_synchronized(_CONFIG_LOCK)
def save_config(cfg=None):
    data = {k: v for k, v in (cfg or CONFIG).items() if not k.startswith('_')}
    os.makedirs(os.path.dirname(CONFIG_PATH), exist_ok=True)
    tmp = '%s.%s.%s.tmp' % (CONFIG_PATH, os.getpid(), secrets.token_hex(4))
    try:
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
            f.flush()
            os.fsync(f.fileno())
        os.replace(tmp, CONFIG_PATH)
    finally:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except OSError:
            pass


