class LogCenter:
    LEVELS = ('INFO', 'OK', 'CMD', 'REVIEW', 'WARN', 'ERROR')

    def __init__(self, path):
        self.path = path
        self._lock = threading.Lock()
        self._gui_queue = queue.Queue()
        self._subscribers = []          # SSE 订阅者队列列表
        self._sub_lock = threading.Lock()
        self.headless = False

    # ---- 核心写日志 ----
    def log(self, level, msg):
        if level not in self.LEVELS:
            level = 'INFO'
        ts = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        line = '[%s] [%-5s] %s' % (ts, level, msg)
        entry = {'time': ts, 'level': level, 'msg': str(msg), 'line': line}

        # 1) 写文件: 每条日志立即 flush + fsync 落盘刷新
        with self._lock:
            try:
                self._rotate_if_needed()
                with open(self.path, 'a', encoding='utf-8') as f:
                    f.write(line + '\n')
                    f.flush()
                    os.fsync(f.fileno())
            except OSError:
                pass

        # 2) 推送到桌面窗口
        try:
            self._gui_queue.put_nowait(entry)
        except queue.Full:
            pass

        # 3) 推送到网页控制台 (WARN/ERROR 额外发 alert 警报事件)
        with self._sub_lock:
            subs = list(self._subscribers)
        for q in subs:
            try:
                q.put_nowait(entry)
            except queue.Full:
                pass

        # 4) 无界面模式输出到控制台
        if self.headless:
            print(line, flush=True)

    def _rotate_if_needed(self):
        try:
            if os.path.exists(self.path) and os.path.getsize(self.path) > LOG_MAX_BYTES:
                bak = self.path + '.1'
                if os.path.exists(bak):
                    os.remove(bak)
                os.replace(self.path, bak)
        except OSError:
            pass

    # ---- SSE 订阅管理 ----
    def subscribe(self):
        q = queue.Queue(maxsize=1000)
        with self._sub_lock:
            self._subscribers.append(q)
        return q

    def unsubscribe(self, q):
        with self._sub_lock:
            if q in self._subscribers:
                self._subscribers.remove(q)

    def recent(self, n=200):
        """读取最近 n 行日志(供网页控制台初始化)"""
        try:
            with open(self.path, 'r', encoding='utf-8', errors='replace') as f:
                lines = f.readlines()
            return [ln.rstrip('\n') for ln in lines[-n:]]
        except OSError:
            return []


LOGGER = LogCenter(CONFIG.get('log_file') or DEFAULT_LOG_FILE)


def log(level, msg):
    LOGGER.log(level, msg)


